(window.HistoryAtlas.PERSONS = window.HistoryAtlas.PERSONS || {})["wolfgang-amadeus-mozart"] = {"id":"wolfgang-amadeus-mozart","name":"沃尔夫冈·阿马德乌斯·莫扎特","name_alt":"Wolfgang Amadeus Mozart","group":"世界","born":1756,"died":1791,"born_approx":false,"died_approx":false,"role":"奥地利作曲家","polity":"神圣罗马帝国","summary":"莫扎特生于萨尔茨堡，幼年随父亲列奥波德巡游欧洲各宫廷演奏，少年时三度赴意大利创作歌剧。成年后任萨尔茨堡大主教宫廷乐师，1781年与大主教决裂，定居维也纳以自由音乐家身份谋生，创作《费加罗的婚礼》《唐璜》《魔笛》等歌剧及大量交响曲、协奏曲。1791年在维也纳去世，《安魂曲》未竟。","confidence":"史料确证","sources":"莫扎特家族书信（《莫扎特书信与笔记全集》）、莫扎特自编作品目录；Otto Erich Deutsch《Mozart: A Documentary Biography》、Maynard Solomon《Mozart: A Life》","stops":[{"year":1756,"to":1756,"x":755.5,"y":161.5,"place":"萨尔茨堡（今奥地利）","event":"1月27日生于萨尔茨堡粮食街，父列奥波德为大主教宫廷乐师。","kind":"出生","confidence":"史料确证","source":"萨尔茨堡大教堂洗礼登记；Deutsch"},{"year":1762,"to":1762,"x":768.2,"y":159.6,"place":"维也纳美泉宫（今奥地利）","event":"10月随父亲与姐姐在美泉宫为女皇玛丽亚·特蕾莎演奏。","kind":"旅行","confidence":"史料确证","source":"列奥波德书信"},{"year":1763,"to":1763,"x":714.5,"y":156.2,"place":"巴黎（今法国）","event":"6月开始历时三年半的西欧巡游，11月抵巴黎，在凡尔赛宫廷演奏，次年初在巴黎首次出版作品。","kind":"旅行","confidence":"史料确证","source":"列奥波德书信；格林《文学通信》"},{"year":1764,"to":1765,"x":705.9,"y":143.5,"place":"伦敦（今英国）","event":"4月抵伦敦，为乔治三世演奏，结识约翰·克里斯蒂安·巴赫，写出最初的交响曲；后经荷兰于1766年返萨尔茨堡。","kind":"旅行","confidence":"史料确证","source":"列奥波德书信；Deutsch"},{"year":1770,"to":1770,"x":753.8,"y":190.8,"place":"罗马（今意大利）","event":"首次意大利之行中，4月在西斯廷礼拜堂听阿莱格里《求主垂怜》后凭记忆写出全曲；7月获教宗授金马刺骑士勋位，年底歌剧《本都王米特里达特》在米兰首演。","kind":"旅行","confidence":"史料确证","source":"列奥波德书信"},{"year":1772,"to":1772,"x":740.8,"y":172.9,"place":"米兰（今意大利）","event":"第三次意大利之行，12月歌剧《卢西奥·西拉》在米兰公爵剧院首演。","kind":"旅行","confidence":"史料确证","source":"列奥波德书信"},{"year":1773,"to":1776,"x":755.5,"y":161.5,"place":"萨尔茨堡（今奥地利）","event":"任新任大主教科洛雷多的宫廷首席小提琴手，创作小提琴协奏曲、交响曲等。","kind":"任职","confidence":"史料确证","source":"Solomon"},{"year":1777,"to":1777,"x":738.3,"y":153.2,"place":"曼海姆（今德国）","event":"辞职后与母亲出游求职，10月抵曼海姆，结识韦伯一家并爱慕阿洛伊西娅·韦伯。","kind":"旅行","confidence":"史料确证","source":"莫扎特书信"},{"year":1778,"to":1778,"x":714.5,"y":156.2,"place":"巴黎（今法国）","event":"3月抵巴黎，求职无果，7月3日母亲病逝于巴黎；年底返乡。","kind":"旅行","confidence":"史料确证","source":"莫扎特书信"},{"year":1779,"to":1779,"x":755.5,"y":161.5,"place":"萨尔茨堡（今奥地利）","event":"1月回到萨尔茨堡，出任宫廷与大教堂管风琴师。","kind":"任职","confidence":"史料确证","source":"Deutsch"},{"year":1780,"to":1780,"x":750.1,"y":160.1,"place":"慕尼黑（今德国）","event":"11月赴慕尼黑创作歌剧《伊多梅纽斯》，次年1月首演。","kind":"其他","confidence":"史料确证","source":"莫扎特书信"},{"year":1781,"to":1785,"x":768.6,"y":159.6,"place":"维也纳（今奥地利）","event":"3月奉召赴维也纳，6月与大主教决裂后定居维也纳；1782年《后宫诱逃》首演，8月与康斯坦策·韦伯在圣斯德望大教堂成婚。","kind":"其他","confidence":"史料确证","source":"莫扎特书信"},{"year":1786,"to":1786,"x":768.6,"y":159.6,"place":"维也纳城堡剧院（今奥地利）","event":"5月1日与达·蓬特合作的歌剧《费加罗的婚礼》在城堡剧院首演。","kind":"其他","confidence":"史料确证","source":"莫扎特自编作品目录"},{"year":1787,"to":1787,"x":760.7,"y":150.3,"place":"布拉格（今捷克）","event":"1月赴布拉格观看《费加罗》的盛演；10月29日《唐璜》在布拉格城邦剧院首演。同年获任皇室室内乐作曲家。","kind":"旅行","confidence":"史料确证","source":"莫扎特书信；Deutsch"},{"year":1789,"to":1789,"x":756.8,"y":138.7,"place":"柏林（今德国）","event":"4至6月北上旅行，经德累斯顿、莱比锡，赴波茨坦与柏林谋求普鲁士宫廷演出机会。","kind":"旅行","confidence":"史料确证","source":"莫扎特致妻子信"},{"year":1790,"to":1790,"x":739.1,"y":150.3,"place":"法兰克福（今德国）","event":"自费赴法兰克福观礼利奥波德二世加冕，10月15日举办音乐会。","kind":"旅行","confidence":"史料确证","source":"莫扎特致妻子信"},{"year":1791,"to":1791,"x":760.7,"y":150.3,"place":"布拉格（今捷克）","event":"9月6日为利奥波德二世加冕波希米亚国王而作的歌剧《狄托的仁慈》在布拉格首演。","kind":"其他","confidence":"史料确证","source":"莫扎特自编作品目录"},{"year":1791,"to":1791,"x":768.6,"y":159.6,"place":"维也纳（今奥地利）","event":"9月30日《魔笛》在维也纳首演；12月5日病逝于维也纳寓所，《安魂曲》未完成。","kind":"去世","confidence":"史料确证","source":"圣斯德望大教堂死亡登记；Deutsch"}]};
